package com.xiaoyang.screenmarker;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;
public class OverlayService extends Service {
 WindowManager wm; FrameLayout root; Board board; LinearLayout toolbar; TextView toggle; int color=Color.RED,tool=0,ci=0; final int[] colors={Color.RED,0xffffd400,Color.CYAN,Color.WHITE,0xff39d353,0xffff66cc};
 public IBinder onBind(Intent i){return null;}
 public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);root=new FrameLayout(this);board=new Board();root.addView(board,new FrameLayout.LayoutParams(-1,-1));toolbar=new LinearLayout(this);toolbar.setOrientation(1);toolbar.setBackgroundColor(0xee20242b);String[][] rows={{"笔","箭头","圆圈","矩形"},{"撤销","单擦","全擦","颜色"},{"收起","关闭"}};for(String[] row:rows){LinearLayout r=new LinearLayout(this);for(String s:row){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setMinWidth(0);b.setPadding(3,0,3,0);r.addView(b,new LinearLayout.LayoutParams(0,48,1));b.setOnClickListener(v->action(s));}toolbar.addView(r);}FrameLayout.LayoutParams bp=new FrameLayout.LayoutParams(-1,-1);bp.gravity=Gravity.TOP;root.addView(toolbar,bp);toggle=new TextView(this);toggle.setText("画笔\n≡");toggle.setTextColor(-1);toggle.setGravity(17);toggle.setBackgroundColor(0xee30343b);FrameLayout.LayoutParams tp=new FrameLayout.LayoutParams(68,58,Gravity.RIGHT|Gravity.CENTER_VERTICAL);root.addView(toggle,tp);toggle.setVisibility(View.GONE);toggle.setOnClickListener(v->{toolbar.setVisibility(View.VISIBLE);toggle.setVisibility(View.GONE);});WindowManager.LayoutParams p=new WindowManager.LayoutParams(-1,-1,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);wm.addView(root,p);}
 void action(String s){switch(s){case "笔":tool=0;break;case "箭头":tool=1;break;case "圆圈":tool=2;break;case "矩形":tool=3;break;case "撤销":if(!board.items.isEmpty())board.items.remove(board.items.size()-1);break;case "单擦":tool=4;break;case "全擦":board.items.clear();break;case "颜色":ci=(ci+1)%colors.length;color=colors[ci];break;case "收起":toolbar.setVisibility(View.GONE);toggle.setVisibility(View.VISIBLE);break;case "关闭":stopSelf();return;}board.invalidate();}
 public void onDestroy(){if(root!=null&&root.isAttachedToWindow())wm.removeView(root);super.onDestroy();}
 class Item{int kind,col;float x,y,ex,ey;ArrayList<PointF> pts=new ArrayList<>();Item(int k,int c,float a,float b){kind=k;col=c;x=ex=a;y=ey=b;}}
 class Board extends View{ArrayList<Item> items=new ArrayList<>();Item cur;Paint p=new Paint(3);Board(){super(OverlayService.this);setLayerType(View.LAYER_TYPE_SOFTWARE,null);setLayerType(View.LAYER_TYPE_HARDWARE,null);setWillNotDraw(false);}protected void onDraw(Canvas c){for(Item i:items)draw(c,i);if(cur!=null)draw(c,cur);}void draw(Canvas c,Item i){p.setColor(i.col);p.setStrokeWidth(i.kind==4?36:7);p.setStyle(Paint.Style.STROKE);p.setStrokeCap(Paint.Cap.ROUND);p.setStrokeJoin(Paint.Join.ROUND);if(i.kind==0||i.kind==4){for(int n=1;n<i.pts.size();n++){PointF a=i.pts.get(n-1),b=i.pts.get(n);c.drawLine(a.x,a.y,b.x,b.y,p);}}else if(i.kind==2)c.drawOval(Math.min(i.x,i.ex),Math.min(i.y,i.ey),Math.max(i.x,i.ex),Math.max(i.y,i.ey),p);else if(i.kind==3)c.drawRect(Math.min(i.x,i.ex),Math.min(i.y,i.ey),Math.max(i.x,i.ex),Math.max(i.y,i.ey),p);else if(i.kind==1){c.drawLine(i.x,i.y,i.ex,i.ey,p);float a=(float)Math.atan2(i.ey-i.y,i.ex-i.x);for(int d=-1;d<=1;d+=2)c.drawLine(i.ex,i.ey,i.ex-30*(float)Math.cos(a+d*.55f),i.ey-30*(float)Math.sin(a+d*.55f),p);}}
 public boolean onTouchEvent(MotionEvent e){if(toolbar.getVisibility()==View.VISIBLE&&e.getRawY()<toolbar.getHeight()+16)return false;float x=e.getRawX(),y=e.getRawY();if(tool==4){if(e.getAction()==0||e.getAction()==2){erase(x,y);invalidate();}return true;}if(e.getAction()==0){cur=new Item(tool,color,x,y);cur.pts.add(new PointF(x,y));invalidate();return true;}if(e.getAction()==2||e.getAction()==1){if(cur==null)return true;cur.ex=x;cur.ey=y;if(tool==0)cur.pts.add(new PointF(x,y));if(e.getAction()==1){items.add(cur);cur=null;}invalidate();return true;}return true;}
 void erase(float x,float y){for(int j=items.size()-1;j>=0;j--){Item i=items.get(j);float cx=(i.x+i.ex)/2,cy=(i.y+i.ey)/2;float d=(float)Math.hypot(x-cx,y-cy);if(i.kind==1)d=Math.min(d,seg(x,y,i.x,i.y,i.ex,i.ey));if(i.kind==0||i.kind==4)for(int n=1;n<i.pts.size();n++){PointF a=i.pts.get(n-1),b=i.pts.get(n);d=Math.min(d,seg(x,y,a.x,a.y,b.x,b.y));}if(d<38){items.remove(j);return;}}}float seg(float x,float y,float a,float b,float c,float d){float dx=c-a,dy=d-b,t=((x-a)*dx+(y-b)*dy)/(dx*dx+dy*dy+.001f);t=Math.max(0,Math.min(1,t));return(float)Math.hypot(x-a-t*dx,y-b-t*dy);}}
}
